//! The checked-in C header (`amos_link.h`) is a **declared mirror** of the Rust ABI in
//! `src/lib.rs` — and until REQ-A715 nothing established that mirror. It is a *generated*
//! artifact (`cbindgen --config cbindgen.toml --crate amos-link-cc --output amos_link.h`)
//! that is committed by hand and never regenerated by any gate, so a Rust signature or a
//! `/// # Safety` contract could change and the header C callers actually compile against
//! would keep the old one — silently, because no test read the header at all.
//!
//! It had already drifted: every one of the 41 `# Safety` contract blocks the crate carries
//! on its exported functions (`must be writable for AMLK_MAX_TOPIC_LEN + 1 bytes`, and the
//! like — the size guarantee that keeps a C caller from a buffer overflow) was **absent**
//! from the shipped header, so the artifact a C programmer reads stated no contract. The
//! crate README justified the absence with "cbindgen only emits declarations" — false for
//! the pinned cbindgen 0.29.4, which emits the doc blocks.
//!
//! These cases read both files as text and bind them without needing cbindgen present:
//!
//! * `the_header_declares_every_exported_symbol` — the set of `amos_link_*` declarations in
//!   the header equals the set of `pub [unsafe] extern "C" fn` exports in `src/lib.rs`
//!   (so a new export with a stale header, or a declaration with no export behind it, is red);
//! * `every_unsafe_export_ships_its_safety_contract` — each exported function whose Rust doc
//!   carries `# Safety` must ship that contract in the comment block immediately above its
//!   declaration in the header, and vice versa.
//!
//! Both sides are extracted by hand (no `regex` dependency) and both assert a **floor** on
//! what they found, so a rewrite that moves the scanned text fails loudly instead of
//! comparing two empty sets.

const HEADER: &str = include_str!("../amos_link.h");
const SOURCE: &str = include_str!("../src/lib.rs");

/// The C declaration name on `line`, if the line starts a declaration of an `amos_link_*`
/// function. Comment and preprocessor lines are skipped: the header's prose names functions
/// too (in the `# Safety` blocks), and those are not declarations.
///
/// The declared name is the `amos_link_*` token that is **immediately followed by `(`** — not
/// simply the first one on the line, because a returned handle spells the type first
/// (`struct amos_link_node *amos_link_node_new(const char *…)`).
fn header_decl_name(line: &str) -> Option<String> {
    let trimmed = line.trim_start();
    if trimmed.starts_with('*') || trimmed.starts_with('/') || trimmed.starts_with('#') {
        return None;
    }
    let mut from = 0;
    while let Some(rel) = line[from..].find("amos_link_") {
        let start = from + rel;
        let rest = &line[start + "amos_link_".len()..];
        let end = rest
            .find(|c: char| !(c.is_ascii_alphanumeric() || c == '_'))
            .unwrap_or(rest.len());
        if rest[end..].starts_with('(') {
            return Some(format!("amos_link_{}", &rest[..end]));
        }
        from = start + "amos_link_".len();
    }
    None
}

/// True when the contiguous C comment block immediately above line `i` contains `# Safety`.
fn header_safety_above(lines: &[&str], i: usize) -> bool {
    let mut j = i;
    let mut block = String::new();
    while j > 0 {
        j -= 1;
        let t = lines[j].trim_start();
        if t.starts_with('*') || t.starts_with("/*") {
            block.push_str(lines[j]);
            block.push('\n');
        } else {
            break;
        }
    }
    block.contains("# Safety")
}

/// Every `amos_link_*` function declared in the header, with whether its preceding comment
/// block carries a `# Safety` section.
fn header_bindings(src: &str) -> Vec<(String, bool)> {
    let lines: Vec<&str> = src.lines().collect();
    let mut out = Vec::new();
    for (i, line) in lines.iter().enumerate() {
        if let Some(name) = header_decl_name(line) {
            out.push((name, header_safety_above(&lines, i)));
        }
    }
    out
}

/// Every `amos_link_*` symbol `src/lib.rs` exports (`pub [unsafe] extern "C" fn`), with
/// whether the `///` doc block attached to it (through any `#[attribute]` lines) carries a
/// `# Safety` section, and whether the function itself is `unsafe`.
fn rust_exports(src: &str) -> Vec<(String, bool, bool)> {
    let lines: Vec<&str> = src.lines().collect();
    let mut out = Vec::new();
    for (i, line) in lines.iter().enumerate() {
        let Some(fn_pos) = line.find("extern \"C\" fn ") else {
            continue;
        };
        // Only public exports: the `pub`/`pub unsafe` must precede `extern "C" fn`.
        let head = &line[..fn_pos];
        if !head.trim_end().ends_with("pub") && !head.trim_end().ends_with("pub unsafe") {
            continue;
        }
        let rest = &line[fn_pos + "extern \"C\" fn ".len()..];
        let end = rest
            .find(|c: char| !(c.is_ascii_alphanumeric() || c == '_'))
            .unwrap_or(rest.len());
        let name = &rest[..end];
        if !name.starts_with("amos_link_") {
            continue;
        }
        let unsafe_fn = head.contains("unsafe");
        // Walk back over the attached `///` doc block and `#[…]` attributes.
        let mut j = i;
        let mut doc = String::new();
        while j > 0 {
            j -= 1;
            let t = lines[j].trim_start();
            if t.starts_with("///") {
                doc.push_str(lines[j]);
                doc.push('\n');
            } else if t.starts_with("#[") || t.starts_with("#!") {
                continue;
            } else {
                break;
            }
        }
        out.push((name.to_string(), doc.contains("# Safety"), unsafe_fn));
    }
    out
}

#[test]
fn the_header_declares_every_exported_symbol_and_nothing_more() {
    let rust = rust_exports(SOURCE);
    let header = header_bindings(HEADER);

    // Floor, not an exact count: the FFI surface grows, so pinning a number would be a
    // maintenance trap — but an extraction that found almost nothing must fail loudly.
    assert!(
        rust.len() >= 50,
        "the Rust scan found only {} exports; it is looking in the wrong place",
        rust.len()
    );
    assert!(
        header.len() >= 50,
        "the header scan found only {} declarations; it is looking in the wrong place",
        header.len()
    );

    let rust_names: std::collections::BTreeSet<&str> =
        rust.iter().map(|(n, _, _)| n.as_str()).collect();
    let header_names: std::collections::BTreeSet<&str> =
        header.iter().map(|(n, _)| n.as_str()).collect();

    let missing_from_header: Vec<&str> = rust_names.difference(&header_names).copied().collect();
    let stale_in_header: Vec<&str> = header_names.difference(&rust_names).copied().collect();
    assert!(
        missing_from_header.is_empty(),
        "exported in src/lib.rs but not declared in amos_link.h (regenerate the header): \
         {missing_from_header:?}"
    );
    assert!(
        stale_in_header.is_empty(),
        "declared in amos_link.h but not exported by src/lib.rs (stale header): {stale_in_header:?}"
    );
}

#[test]
fn every_unsafe_export_ships_its_safety_contract() {
    let rust = rust_exports(SOURCE);
    let header: std::collections::BTreeMap<String, bool> =
        header_bindings(HEADER).into_iter().collect();

    let mut missing = Vec::new();
    for (name, rust_has_safety, unsafe_fn) in &rust {
        let header_has_safety = header.get(name).copied().unwrap_or(false);
        // The crate's own promise: "Every `pub unsafe extern "C" fn` says, in its `# Safety`
        // section, what the C caller must guarantee." Enforce it in both directions.
        let want = *rust_has_safety || *unsafe_fn;
        if want != header_has_safety {
            missing.push(format!(
                "{name}: Rust doc has_safety={rust_has_safety} unsafe={unsafe_fn}, \
                 header has_safety={header_has_safety}"
            ));
        }
        if *unsafe_fn && !rust_has_safety {
            missing.push(format!(
                "{name}: an `unsafe extern \"C\" fn` with no `# Safety` section in src/lib.rs"
            ));
        }
    }
    assert!(
        missing.is_empty(),
        "the header's safety contracts drifted from the Rust ABI:\n  {}",
        missing.join("\n  ")
    );
}
